    <script>
        document.addEventListener('DOMContentLoaded', function () {
            const markers       = document.querySelectorAll('.partners__map-item');
            const cards         = document.querySelectorAll('.partners__map-item-desc');
            const allLocations  = document.querySelectorAll('.partners__item');
            if (!markers.length || !cards.length) {
                console.warn('Markers or cards not found');
                return;
            }
            function deactivateAll() {
                markers.forEach(m => m.classList.remove('is-active'));
                cards.forEach(c => c.classList.remove('is-active'));
                allLocations.forEach(loc => loc.classList.remove('is-active'));
            }
            markers.forEach(marker => {
                marker.addEventListener('click', function () {
                    const id = this.getAttribute('data-id');
                    if (!id) return;
                    const card = document.querySelector('.partners__map-item-desc[data-id="' + id + '"]');
                    if (!card) return;
                    const currentLocations = document.querySelectorAll('.partners__item[data-id="' + id + '"]');
                    const already = this.classList.contains('is-active');
                    deactivateAll();
                    if (already) {
                        return;
                    }
                    this.classList.add('is-active');
                    card.classList.add('is-active');
                    currentLocations.forEach(loc => {
                        loc.classList.add('is-active');
                    });
                });
            });

            document.addEventListener('click', function (e) {
                if (
                    e.target.closest('.partners__map-item') ||
                    e.target.closest('.partners__map-item-desc')
                ) {
                    return;
                }

                deactivateAll();
            });
        });
    </script>

    <script>
        document.addEventListener('DOMContentLoaded', function () {
            // Находим все слайдеры на странице
            var sliders = document.querySelectorAll('.country__list.swiper-container');

            if (!sliders.length) return;

            sliders.forEach(function (container, index) {
                var wrapper      = container.querySelector('.swiper-wrapper');
                var paginationEl = container.querySelector('.swiper-pagination');
                var nextEl       = container.querySelector('.swiper-navigation .next');
                var prevEl       = container.querySelector('.swiper-navigation .prev');

                // Если по какой-то причине верстка битая — пропускаем
                if (!wrapper) return;

                var options = {
                    slidesPerView: 1,
                    spaceBetween: 16,
                    loop: true,
                    effect: "fade",
                    fadeEffect: {
                        crossFade: true,
                    },
                    pagination: {
                        el: paginationEl,
                        type: 'custom',
                        renderCustom: function (swiper, current, total) {
                            return '<span class="country-pagination-current">' + current +
                                '</span> / <span class="country-pagination-total">' + total + '</span>';
                        }
                    },
                    navigation: {
                        nextEl: nextEl,
                        prevEl: prevEl
                    }
                };

                // Инициализация Swiper для конкретного контейнера
                var swiper = new Swiper(container, options);

                // если вдруг где-то пригодится — сохраним инстанс на элементе
                container.swiperInstance = swiper;
            });
        });
    </script>

